30	namespace cvcuda::priv {
31	namespace hq_resize {
32	
33	namespace {
34	
35	// Expand a planar (NCHW/CHW) tensor batch into a batch of single-channel (H,W,1) HWC views, one per
36	// (sample, channel) plane. HQResize resizes channels independently, so resizing each plane as an
37	// independent single-channel image reproduces the interleaved result bit-for-bit. The views alias
38	// the original device memory (no copy); the returned batch must outlive the operator call. The
39	// caller sizes the workspace from the matching expanded (sum-of-channels single-channel) shapes.
40	static nvcv::TensorBatch ExpandPlanarTensorBatch(const nvcv::TensorBatch &batch)
41	{
42	    std::vector<nvcv::Tensor> views;
43	    for (int i = 0; i < batch.numTensors(); ++i)
44	    {
45	        nvcv::Tensor tensor = batch[i];
46	        auto         data   = tensor.exportData<nvcv::TensorDataStridedCuda>();
47	        if (!data)
48	        {
49	            throw nvcv::Exception(nvcv::Status::ERROR_INVALID_ARGUMENT,
50	                                  "Planar HQResize requires cuda-accessible "
51	                                  "tensors");
52	        }
53	        auto access = nvcv::TensorDataAccessStridedImagePlanar::Create(*data);
54	        if (!access)
55	        {
56	            throw nvcv::Exception(nvcv::Status::ERROR_INVALID_ARGUMENT,
57	                                  "Planar HQResize requires planar-accessible "
58	                                  "tensors");
59	        }
60	
61	        const int     numSamples  = access->numSamples();
62	        const int     numChannels = access->numChannels();
63	        const int64_t H = access->numRows(), W = access->numCols();
64	        for (int s = 0; s < numSamples; ++s)
65	        {
66	            for (int c = 0; c < numChannels; ++c)
67	            {
68	                nvcv::TensorDataStridedCuda::Buffer buf;
69	                buf.basePtr    = reinterpret_cast<NVCVByte *>(access->sampleData(s) + c * access->chStride());
70	                buf.strides[0] = access->rowStride(); // H
71	                buf.strides[1] = access->colStride(); // W
72	                buf.strides[2] = access->colStride(); // C == 1
73	                nvcv::TensorDataStridedCuda viewData{
74	                    nvcv::TensorShape{{H, W, 1}, "HWC"},
75	                    data->dtype(), buf
76	                };
77	                views.push_back(nvcv::TensorWrapData(viewData));
78	            }
79	        }
80	    }
81	    nvcv::TensorBatch out(static_cast<int32_t>(views.size()));
82	    out.pushBack(views.begin(), views.end());
83	    return out;
84	}
85	
86	} // namespace
