88	class HQResizeImpl final : public IHQResizeImpl
89	{
90	public:
91	    HQResizeImpl()
92	        : m_impl2d(makeImpl2D())
93	        , m_impl3d(makeImpl3D())
94	    {
95	    }
96	
97	    cvcuda::WorkspaceRequirements getWorkspaceRequirements(int numSamples, const HQResizeTensorShapeI inputShape,
98	                                                           const HQResizeTensorShapeI  outputShape,
99	                                                           const NVCVInterpolationType minInterpolation,
100	                                                           const NVCVInterpolationType magInterpolation, bool antialias,
101	                                                           const HQResizeRoiF *roi) const override
102	    {
103	        return implForNDim(inputShape.ndim)
104	            .getWorkspaceRequirements(numSamples, inputShape, outputShape, minInterpolation, magInterpolation,
105	                                      antialias, roi);
106	    }
107	
108	    cvcuda::WorkspaceRequirements getWorkspaceRequirements(int numSamples, const HQResizeTensorShapesI inputShapes,
109	                                                           const HQResizeTensorShapesI outputShapes,
110	                                                           const NVCVInterpolationType minInterpolation,
111	                                                           const NVCVInterpolationType magInterpolation, bool antialias,
112	                                                           const HQResizeRoisF rois) const override
113	    {
114	        return implForNDim(inputShapes.ndim)
115	            .getWorkspaceRequirements(numSamples, inputShapes, outputShapes, minInterpolation, magInterpolation,
116	                                      antialias, rois);
117	    }
118	
119	    cvcuda::WorkspaceRequirements getWorkspaceRequirements(int                        maxBatchSize,
120	                                                           const HQResizeTensorShapeI maxShape) const override
121	    {
122	        return implForNDim(maxShape.ndim).getWorkspaceRequirements(maxBatchSize, maxShape);
123	    }
124	
125	    void operator()(cudaStream_t stream, const cvcuda::Workspace &ws, const nvcv::Tensor &src, const nvcv::Tensor &dst,
126	                    const NVCVInterpolationType minInterpolation, const NVCVInterpolationType magInterpolation,
127	                    bool antialias, const HQResizeRoiF *roi) override
128	    {
129	        CVCUDA_NVTX_RANGE("cvcuda::hq_resize::HQResizeImpl::operator()[Tensor]");
130	        bool is3d = src.layout().find('D') >= 0;
131	        implForNDim(is3d ? 3 : 2)(stream, ws, src, dst, minInterpolation, magInterpolation, antialias, roi);
132	    }
133	
134	    void operator()(cudaStream_t stream, const cvcuda::Workspace &ws, const nvcv::ImageBatchVarShape &src,
135	                    const nvcv::ImageBatchVarShape &dst, const NVCVInterpolationType minInterpolation,
136	                    const NVCVInterpolationType magInterpolation, bool antialias, const HQResizeRoisF rois) override
137	    {
138	        CVCUDA_NVTX_RANGE("cvcuda::hq_resize::HQResizeImpl::operator()[ImageBatchVarShape]");
139	        (*m_impl2d)(stream, ws, src, dst, minInterpolation, magInterpolation, antialias, rois);
140	    }
141	
142	    void operator()(cudaStream_t stream, const cvcuda::Workspace &ws, const nvcv::TensorBatch &src,
143	                    const nvcv::TensorBatch &dst, const NVCVInterpolationType minInterpolation,
144	                    const NVCVInterpolationType magInterpolation, bool antialias, const HQResizeRoisF rois) override
145	    {
146	        CVCUDA_NVTX_RANGE("cvcuda::hq_resize::HQResizeImpl::operator()[TensorBatch]");
147	        // Planar (channel-first 2D, NCHW/CHW) batches are expanded into single-channel (H,W,1) plane
148	        // views and run through the regular 2D path; the views alias the originals so the result is
149	        // bit-identical to the interleaved path. Views are kept alive for the duration of the call.
150	        const nvcv::TensorLayout layout = src.layout();
151	        if (layout == nvcv::TENSOR_NCHW || layout == nvcv::TENSOR_CHW)
152	        {
153	            nvcv::TensorBatch planarSrc = ExpandPlanarTensorBatch(src);
154	            nvcv::TensorBatch planarDst = ExpandPlanarTensorBatch(dst);
155	            (*m_impl2d)(stream, ws, planarSrc, planarDst, minInterpolation, magInterpolation, antialias, rois);
156	            return;
157	        }
158	        bool is3d = layout.find('D') >= 0;
159	        implForNDim(is3d ? 3 : 2)(stream, ws, src, dst, minInterpolation, magInterpolation, antialias, rois);
160	    }
161	
162	private:
163	    IHQResizeImpl &implForNDim(int ndim) const
164	    {
165	        if (ndim == 2)
166	            return *m_impl2d;
167	        if (ndim == 3)
168	            return *m_impl3d;
169	        throw nvcv::Exception(nvcv::Status::ERROR_INVALID_ARGUMENT,
170	                              "Only 2D or 3D resize is supported. Got unexpected number of extents to resize.");
171	    }
172	
173	    std::unique_ptr<IHQResizeImpl> m_impl2d;
174	    std::unique_ptr<IHQResizeImpl> m_impl3d;
175	};
176	
177	} // namespace hq_resize
