51	    const int x_offset = blockIdx.x * blockDim.x;
52	
53	    PillowPrecomputeCoeffs<Filter>(xx, local_id, x_offset, in_size, in0, scale, filterscale, support, out_size, k_size,
54	                                   filterp, bounds_out, kk_out, normalize_coeff, use_share_mem, precision_bits);
55	}
56	
57	// SrcPtr2d / DstPtr2d are Ptr2dNHWC (interleaved) or Ptr2dNCHW (planar). Both expose the same
58	// ptr(b, y, x, c) / rows / cols / ch interface, so one kernel handles both layouts. For planar the
59	// grid is launched with one z-slice per sample (not per N*C flattened plane), and the per-output-
60	// pixel bounds / weight-pointer setup is computed once and reused across all `ch` planes -- amortizing
61	// the work the flattened single-channel view would otherwise repeat once per channel.
62	//
63	// NC is the compile-time channel count for the interleaved (NHWC) path: the channels of one output
64	// pixel are contiguous in memory, so the whole pixel is loaded/stored as one `MakeType<T, NC>` vector
65	// and accumulated in a `MakeType<work_type, NC>` register. This collapses the per-channel scalar loop
66	// (NC separate 1-byte loads + NC full ptr() index computations per tap) into a single wide, coalesced
67	// access per tap -- the resize passes are issue-bound on that per-channel address arithmetic, not on
68	// bandwidth. NC == 0 selects the original scalar channel loop, used for the planar (NCHW) layout where
69	// the channels live in separate planes and are not contiguous.
70	template<int NC, class T, class Filter, class SrcPtr2d, class DstPtr2d>
71	__global__ void horizontal_pass(const SrcPtr2d src, DstPtr2d dst, NVCVRectI roi, Filter &filterp, int h_ksize,
72	                                int v_ksize, int *h_bounds, work_type *h_kk, int *v_bounds, work_type *v_kk,
73	                                work_type init_buffer, bool round_up, bool use_share_mem)
74	{
75	    const int dst_x      = blockIdx.x * blockDim.x + threadIdx.x;
76	    const int dst_y      = blockIdx.y * blockDim.y + threadIdx.y;
77	    const int local_x    = threadIdx.x;
78	    const int x_offset   = blockIdx.x * blockDim.x;
79	    const int batch_idx  = get_batch_idx();
80	    int       out_height = dst.rows, out_width = dst.cols;
81	
82	    extern __shared__ __align__(sizeof(work_type)) unsigned char kk_smem_h[];
83	    work_type *h_k_tmp = PillowStageCoeffs(h_kk, reinterpret_cast<work_type *>(kk_smem_h), x_offset, h_ksize, out_width,
84	                                           blockDim.x, use_share_mem);
85	
86	    if (dst_x < out_width && dst_y < out_height)
87	    {
88	        int xmin = h_bounds[dst_x * 2];
89	        int xmax = h_bounds[dst_x * 2 + 1];
90	
91	        work_type *h_k = &h_k_tmp[local_x * h_ksize];
92	
93	        if constexpr (NC > 0)
94	        {
95	            // Interleaved: load the contiguous NC-channel pixel as one vector; advance one pixel
96	            // (NC elements) per horizontal tap.
97	            using vec_t   = cuda::MakeType<T, NC>;
98	            using accum_t = cuda::MakeType<work_type, NC>;
99	
100	            const std::byte *p    = reinterpret_cast<const std::byte *>(src.ptr(batch_idx, dst_y, xmin, 0));
101	            accum_t          h_ss = cuda::SetAll<accum_t>(work_type{0});
102	            for (int x = 0; x < xmax; ++x)
103	            {
104	                h_ss = h_ss + h_k[x] * cuda::StaticCast<work_type>(*reinterpret_cast<const vec_t *>(p));
105	                p += sizeof(vec_t);
106	            }
107	
108	            vec_t *out = reinterpret_cast<vec_t *>(dst.ptr(batch_idx, dst_y, dst_x, 0));
109	            if (round_up)
110	            {
111	                // Signed-integer path keeps std::round (half away from zero) per channel for bit
112	                // exactness with the scalar path; cuda::round has no half-away mode.
113	                work_type *acc = reinterpret_cast<work_type *>(&h_ss);
114	#pragma unroll
115	                for (int c = 0; c < NC; ++c) reinterpret_cast<T *>(out)[c] = cuda::SaturateCast<T>(std::round(acc[c]));
116	            }
117	            else
118	            {
119	                *out = cuda::SaturateCast<vec_t>(h_ss);
120	            }
121	        }
122	        else
123	        {
124	            for (int c = 0; c < src.ch; ++c)
125	            {
126	                work_type h_ss = 0.0;
127	                for (int x = 0; x < xmax; ++x)
128	                {
129	                    h_ss = h_ss + *src.ptr(batch_idx, dst_y, x + xmin, c) * h_k[x];
130	                }
131	
132	                if (round_up)
133	                    *dst.ptr(batch_idx, dst_y, dst_x, c) = cuda::SaturateCast<T>(std::round(h_ss));
134	                else
135	                    *dst.ptr(batch_idx, dst_y, dst_x, c) = cuda::SaturateCast<T>(h_ss);
136	            }
137	        }
138	    }
139	}
140	
141	// Interleaved horizontal pass computing two adjacent output pixels per thread. Neighboring tap
142	// windows overlap by roughly k minus the scale step, so the shared segment is loaded once and
143	// accumulated into both outputs. Three unpredicated segment loops (prefix / shared / suffix) keep
144	// the fma count and the ascending per-output tap order identical to horizontal_pass (bit-exact);
145	// only the load count drops. The launch site doubles the block's output span for the staged
146	// coefficients.
147	template<int NC, class T, class Filter, class SrcPtr2d, class DstPtr2d>
148	__global__ void horizontal_pass_paired(const SrcPtr2d src, DstPtr2d dst, NVCVRectI roi, Filter &filterp, int h_ksize,
149	                                       int v_ksize, int *h_bounds, work_type *h_kk, int *v_bounds, work_type *v_kk,
150	                                       work_type init_buffer, bool round_up, bool use_share_mem)
151	{
152	    static_assert(NC > 0, "paired horizontal pass is the interleaved channel-vectorized path");
153	    const int pair0      = (blockIdx.x * blockDim.x + threadIdx.x) * 2;
154	    const int dst_y      = blockIdx.y * blockDim.y + threadIdx.y;
155	    const int local_x    = threadIdx.x;
156	    const int x_offset   = blockIdx.x * blockDim.x * 2;
157	    const int batch_idx  = get_batch_idx();
158	    int       out_height = dst.rows, out_width = dst.cols;
159	
160	    extern __shared__ __align__(sizeof(work_type)) unsigned char kk_smem_hq[];
161	    work_type *h_k_tmp = PillowStageCoeffs(h_kk, reinterpret_cast<work_type *>(kk_smem_hq), x_offset, h_ksize,
162	                                           out_width, blockDim.x * 2, use_share_mem);
163	
164	    if (pair0 < out_width && dst_y < out_height)
165	    {
166	        using vec_t   = cuda::MakeType<T, NC>;
167	        using accum_t = cuda::MakeType<work_type, NC>;
168	
169	        const bool has1  = pair0 + 1 < out_width;
170	        const int  xmin0 = h_bounds[pair0 * 2];
171	        const int  xmax0 = h_bounds[pair0 * 2 + 1];
172	        const int  end0  = xmin0 + xmax0;
173	        // Without a second output, park its window at end0 so the shared and suffix loops are
174	        // empty and k1 (one slot past this image's coefficients) is never read.
175	        const int  xmin1 = has1 ? h_bounds[(pair0 + 1) * 2] : end0;
176	        const int  xmax1 = has1 ? h_bounds[(pair0 + 1) * 2 + 1] : 0;
177	
178	        work_type *k0 = &h_k_tmp[(local_x * 2) * h_ksize];
179	        work_type *k1 = &h_k_tmp[(local_x * 2 + 1) * h_ksize];
180	
181	        const int end1 = xmin1 + xmax1;
182	
183	        accum_t s0 = cuda::SetAll<accum_t>(work_type{0});
184	        accum_t s1 = cuda::SetAll<accum_t>(work_type{0});
185	
186	        const std::byte *base   = reinterpret_cast<const std::byte *>(src.ptr(batch_idx, dst_y, 0, 0));
187	        const int        preEnd = min(xmin1, end0);
188	        for (int x = xmin0; x < preEnd; ++x)
189	        {
190	            s0 = s0
191	               + k0[x - xmin0]
192	                     * cuda::StaticCast<work_type>(
193	                         *reinterpret_cast<const vec_t *>(base + static_cast<size_t>(x) * sizeof(vec_t)));
194	        }
195	        for (int x = xmin1; x < end0; ++x)
196	        {
197	            const accum_t px = cuda::StaticCast<work_type>(
198	                *reinterpret_cast<const vec_t *>(base + static_cast<size_t>(x) * sizeof(vec_t)));
199	            s0 = s0 + k0[x - xmin0] * px;
200	            s1 = s1 + k1[x - xmin1] * px;
201	        }
202	        const int sufBegin = max(xmin1, end0);
203	        for (int x = sufBegin; x < end1; ++x)
204	        {
205	            s1 = s1
206	               + k1[x - xmin1]
207	                     * cuda::StaticCast<work_type>(
208	                         *reinterpret_cast<const vec_t *>(base + static_cast<size_t>(x) * sizeof(vec_t)));
209	        }
210	
211	        vec_t *out0 = reinterpret_cast<vec_t *>(dst.ptr(batch_idx, dst_y, pair0, 0));
212	        if (round_up)
213	        {
214	            work_type *acc0 = reinterpret_cast<work_type *>(&s0);
215	#pragma unroll
216	            for (int c = 0; c < NC; ++c) reinterpret_cast<T *>(out0)[c] = cuda::SaturateCast<T>(std::round(acc0[c]));
217	        }
218	        else
219	        {
220	            *out0 = cuda::SaturateCast<vec_t>(s0);
221	        }
222	        if (has1)
223	        {
224	            vec_t *out1 = reinterpret_cast<vec_t *>(dst.ptr(batch_idx, dst_y, pair0 + 1, 0));
225	            if (round_up)
226	            {
227	                work_type *acc1 = reinterpret_cast<work_type *>(&s1);
228	#pragma unroll
229	                for (int c = 0; c < NC; ++c)
230	                    reinterpret_cast<T *>(out1)[c] = cuda::SaturateCast<T>(std::round(acc1[c]));
231	            }
232	            else
233	            {
234	                *out1 = cuda::SaturateCast<vec_t>(s1);
235	            }
236	        }
237	    }
238	}
239	
240	template<int PC, class T, class Filter, class SrcPtr2d, class DstPtr2d>
241	__global__ void horizontal_pass_planar_channels(const SrcPtr2d src, DstPtr2d dst, NVCVRectI roi, Filter &filterp,
242	                                                int h_ksize, int v_ksize, int *h_bounds, work_type *h_kk, int *v_bounds,
243	                                                work_type *v_kk, work_type init_buffer, bool round_up,
244	                                                bool use_share_mem)
245	{
246	    const int dst_x      = blockIdx.x * blockDim.x + threadIdx.x;
247	    const int dst_y      = blockIdx.y * blockDim.y + threadIdx.y;
248	    const int local_x    = threadIdx.x;
249	    const int x_offset   = blockIdx.x * blockDim.x;
250	    const int batch_idx  = get_batch_idx();
251	    int       out_height = dst.rows, out_width = dst.cols;
252	
253	    extern __shared__ __align__(sizeof(work_type)) unsigned char kk_smem_hp[];
254	    work_type *h_k_tmp = PillowStageCoeffs(h_kk, reinterpret_cast<work_type *>(kk_smem_hp), x_offset, h_ksize,
255	                                           out_width, blockDim.x, use_share_mem);
256	
257	    if (dst_x < out_width && dst_y < out_height)
258	    {
259	        int        xmin = h_bounds[dst_x * 2];
260	        int        xmax = h_bounds[dst_x * 2 + 1];
261	        work_type *h_k  = &h_k_tmp[local_x * h_ksize];
262	        work_type  h_ss[PC];
263	
264	#pragma unroll
265	        for (int c = 0; c < PC; ++c)
266	        {
267	            h_ss[c] = 0.0;
268	        }
269	
270	        // Hoist the per-plane row pointers: the tap loop then advances plain pointers instead of
271	        // re-deriving the full (b, y, x, c) offset for every tap of every plane. Three byte planes
272	        // only: at four planes the extra pointer registers measured 3.5-6.6% slower on multi-tap
273	        // rows, and float planes regressed contract cubic 6-16%.
274	        if constexpr (PC == 3 && sizeof(T) == 1)
275	        {
276	            const T *row[PC];
277	#pragma unroll
278	            for (int c = 0; c < PC; ++c) row[c] = src.ptr(batch_idx, dst_y, xmin, c);
279	
280	            for (int x = 0; x < xmax; ++x)
281	            {
282	                const work_type k = h_k[x];
283	#pragma unroll
284	                for (int c = 0; c < PC; ++c)
285	                {
286	                    h_ss[c] = h_ss[c] + row[c][x] * k;
287	                }
288	            }
289	        }
290	        else
291	        {
292	            for (int x = 0; x < xmax; ++x)
293	            {
294	                const work_type k = h_k[x];
295	#pragma unroll
296	                for (int c = 0; c < PC; ++c)
297	                {
298	                    h_ss[c] = h_ss[c] + *src.ptr(batch_idx, dst_y, x + xmin, c) * k;
299	                }
300	            }
301	        }
302	
303	#pragma unroll
304	        for (int c = 0; c < PC; ++c)
305	        {
306	            if (round_up)
307	                *dst.ptr(batch_idx, dst_y, dst_x, c) = cuda::SaturateCast<T>(std::round(h_ss[c]));
308	            else
309	                *dst.ptr(batch_idx, dst_y, dst_x, c) = cuda::SaturateCast<T>(h_ss[c]);
310	        }
311	    }
312	}
313	
314	template<int NC, class T, class Filter, class SrcPtr2d, class DstPtr2d>
315	__global__ void vertical_pass(const SrcPtr2d src, DstPtr2d dst, NVCVRectI roi, Filter &filterp, int h_ksize,
316	                              int v_ksize, int *h_bounds, work_type *h_kk, int *v_bounds, work_type *v_kk,
317	                              work_type init_buffer, bool round_up, bool use_share_mem)
318	{
319	    const int dst_x      = blockIdx.x * blockDim.x + threadIdx.x;
320	    const int dst_y      = blockIdx.y * blockDim.y + threadIdx.y;
321	    const int local_y    = threadIdx.y;
322	    const int y_offset   = blockIdx.y * blockDim.y;
323	    const int batch_idx  = get_batch_idx();
324	    int       out_height = dst.rows, out_width = dst.cols;
325	
326	    extern __shared__ __align__(sizeof(work_type)) unsigned char kk_smem_v[];
327	    work_type *v_k_tmp = PillowStageCoeffs(v_kk, reinterpret_cast<work_type *>(kk_smem_v), y_offset, v_ksize,
328	                                           out_height, blockDim.y, use_share_mem);
329	
330	    if (dst_x < out_width && dst_y < out_height)
331	    {
332	        int ymin = v_bounds[dst_y * 2];
333	        int ymax = v_bounds[dst_y * 2 + 1];
334	
335	        work_type *v_k = &v_k_tmp[local_y * v_ksize];
336	
337	        if constexpr (NC > 0)
338	        {
339	            // Interleaved: load the contiguous NC-channel pixel as one vector; advance one row
340	            // (rowStride bytes) per vertical tap.
341	            using vec_t   = cuda::MakeType<T, NC>;
342	            using accum_t = cuda::MakeType<work_type, NC>;
343	
344	            const std::byte *p  = reinterpret_cast<const std::byte *>(src.ptr(batch_idx, ymin, dst_x, 0));
345	            accum_t          ss = cuda::SetAll<accum_t>(init_buffer);
346	            for (int y = 0; y < ymax; ++y)
347	            {
348	                ss = ss + v_k[y] * cuda::StaticCast<work_type>(*reinterpret_cast<const vec_t *>(p));
349	                p += src.rowStride;
350	            }
351	
352	            vec_t *out = reinterpret_cast<vec_t *>(dst.ptr(batch_idx, dst_y, dst_x, 0));
353	            if (round_up)
354	            {
355	                work_type *acc = reinterpret_cast<work_type *>(&ss);
356	#pragma unroll
357	                for (int c = 0; c < NC; ++c) reinterpret_cast<T *>(out)[c] = cuda::SaturateCast<T>(std::round(acc[c]));
358	            }
359	            else
360	            {
361	                *out = cuda::SaturateCast<vec_t>(ss);
362	            }
363	        }
364	        else
365	        {
366	            for (int c = 0; c < src.ch; ++c)
367	            {
368	                work_type ss = init_buffer;
369	                for (int y = 0; y < ymax; ++y)
370	                {
371	                    ss = ss + *src.ptr(batch_idx, y + ymin, dst_x, c) * v_k[y];
372	                }
373	
374	                if (round_up)
375	                    *dst.ptr(batch_idx, dst_y, dst_x, c) = cuda::SaturateCast<T>(std::round(ss));
376	                else
377	                    *dst.ptr(batch_idx, dst_y, dst_x, c) = cuda::SaturateCast<T>(ss);
378	            }
379	        }
380	    }
381	}
382	
383	// Interleaved (NHWC) vertical pass vectorized along the flattened row. The vertical weights depend
384	// only on dst_y, so all cols*ch scalars of an output row share v_k: each thread accumulates VEC
385	// consecutive scalars with one MakeType<T, VEC> load per tap instead of one per-pixel channel
386	// vector, cutting the load/store and address-arithmetic issue count these passes are bound on.
387	// Per-element arithmetic (taps, order, cast, saturate) is identical to vertical_pass. The launch
388	// site gates on vector alignment of both buffers; the row tail falls back to a scalar loop.
389	template<int VEC, class T, class Filter, class SrcPtr2d, class DstPtr2d>
390	__global__ void vertical_pass_vec(const SrcPtr2d src, DstPtr2d dst, NVCVRectI roi, Filter &filterp, int h_ksize,
391	                                  int v_ksize, int *h_bounds, work_type *h_kk, int *v_bounds, work_type *v_kk,
392	                                  work_type init_buffer, bool round_up, bool use_share_mem)
393	{
394	    const int elem0      = (blockIdx.x * blockDim.x + threadIdx.x) * VEC;
395	    const int dst_y      = blockIdx.y * blockDim.y + threadIdx.y;
396	    const int local_y    = threadIdx.y;
397	    const int y_offset   = blockIdx.y * blockDim.y;
398	    const int batch_idx  = get_batch_idx();
399	    const int out_height = dst.rows;
400	    const int row_elems  = dst.cols * dst.ch;

