219	// Per-thread resampling-coefficient computation for one output position, shared by the tensor
220	// (`_precomputeCoeffs`) and var-shape (`_precomputeCoeffsVarShape`) precompute kernels. The two only
221	// differ in how they fetch their scalar parameters (direct kernel args vs. per-image arrays) and in
222	// the fixed-point `precision` shift, so the math itself lives here once. Writes the resampling weights
223	// into `kk_out` (cooperatively staged through shared memory when `use_share_mem`) and the [xmin, xmax)
224	// support bounds for output index `xx` into `bounds_out`.
225	template<class Filter>
226	__device__ inline void PillowPrecomputeCoeffs(int xx, int local_id, int x_offset, int in_size, int in0, work_type scale,
227	                                              work_type filterscale, work_type support, int out_size, int k_size,
228	                                              Filter &filterp, int *bounds_out, work_type *kk_out, bool normalize_coeff,
229	                                              bool use_share_mem, unsigned int precision)
230	{
231	    work_type *kk = kk_out + x_offset * k_size;
232	    if (use_share_mem)
