240	        int             x          = 0;
241	        int             xmin       = 0;
242	        int             xmax       = 0;
243	        work_type       center     = 0;
244	        work_type       ww         = 0;
245	        work_type       ss         = 0;
246	        const work_type half_pixel = 0.5;
247	
248	        center = in0 + (xx + half_pixel) * scale;
249	        ww     = 0.0;
250	        ss     = 1.0 / filterscale;
251	        // Round the value.
252	        xmin = static_cast<int>(center - support + half_pixel);
253	        if (xmin < 0)
254	        {
255	            xmin = 0;
256	        }
257	        // Round the value.
258	        xmax = static_cast<int>(center + support + half_pixel);
259	        if (xmax > in_size)
260	        {
261	            xmax = in_size;
262	        }
263	        xmax -= xmin;
264	        work_type *k = &kk[local_id * k_size];
265	        for (x = 0; x < xmax; ++x)
266	        {
267	            work_type w = filterp.filter((x + xmin - center + half_pixel) * ss);
268	            k[x]        = w;
269	            ww += w;
270	        }
271	        for (x = 0; x < xmax; ++x)
272	        {
273	            if (std::fabs(ww) > 1e-5)
274	            {
275	                k[x] /= ww;
276	            }
277	        }
278	        // Remaining values should stay empty if they are used despite of xmax.
279	        for (; x < k_size; ++x)
280	        {
281	            k[x] = .0f;
282	        }
283	        if (normalize_coeff)
284	        {
285	            for (int i = 0; i < k_size; i++)
286	            {
287	                work_type val = k[i];
288	                if (val < 0)
289	                {
290	                    k[i] = static_cast<int>(-half_pixel + val * (1U << precision));
291	                }
292	                else
293	                {
294	                    k[i] = static_cast<int>(half_pixel + val * (1U << precision));
295	                }
296	            }
297	        }
298	
299	        bounds_out[xx * 2]     = xmin;
300	        bounds_out[xx * 2 + 1] = xmax;
301	    }
302	    if (use_share_mem)
303	    {
304	        __syncthreads();
305	        for (int i = local_id; i < (out_size - x_offset) * k_size && i < blockDim.x * k_size; i += blockDim.x)
306	        {
307	            kk_out[x_offset * k_size + i] = kk[i];
308	        }
309	    }
310	}
