135	struct ResamplingFilter
136	{
137	    float *coeffs;
138	    int    numCoeffs;
139	    float  anchor; // support / 2
140	    float  scale;  // (numCoeffs - 1) / support
141	
142	    void rescale(float support)
143	    {
144	        float old_scale = scale;
145	        scale           = (numCoeffs - 1) / support;
146	        anchor          = anchor * old_scale / scale;
147	    }
148	
149	    __host__ __device__ int support() const
150	    {
151	        return ceilf((numCoeffs - 1) / scale);
152	    }
153	
154	    __device__ float operator()(float x) const
155	    {
156	        if (!(x > -1)) // negative and NaN arguments
157	            return 0;
158	        if (x >= numCoeffs)
159	            return 0;
160	        int   x0 = floorf(x);
161	        int   x1 = x0 + 1;
162	        float d  = x - x0;
163	        float f0 = x0 < 0 ? 0.0f : __ldg(coeffs + x0);
164	        float f1 = x1 >= numCoeffs ? 0.0f : __ldg(coeffs + x1);
165	        return f0 + d * (f1 - f0);
166	    }
167	};
