178	inline float CubicWindow(float x)
179	{
180	    x = fabsf(x);
181	    if (x >= 2)
182	        return 0;
183	
184	    float x2 = x * x;
185	    float x3 = x2 * x;
186	    if (x > 1)
187	        return -0.5f * x3 + 2.5f * x2 - 4.0f * x + 2.0f;
188	    else
189	        return 1.5f * x3 - 2.5f * x2 + 1.0f;
190	}
