231	                   float x = 4 * (i - (filter.numCoeffs - 1) * 0.5f) / (filter.numCoeffs - 1);
232	                   return CubicWindow(x);
233	               });
234	    filter.rescale(4); // rescaling to the minimal allowed support
235	}
