237	class ResamplingFiltersFactory
238	{
239	public:
240	    enum FilterIdx
241	    {
242	        Idx_Triangular = 0,
243	        Idx_Gaussian,
244	        Idx_Lanczos3,
245	        Idx_Cubic,
246	        kNumFilters
247	    };
248	
249	    static constexpr int kLanczosResolution = 32;
250	    static constexpr int kLanczosA          = 3;
251	
252	    static constexpr int kTriangularSize = 3;
253	    static constexpr int kGaussianSize   = 65;
254	    static constexpr int kCubicSize      = 129;
255	    static constexpr int kLanczosSize    = (2 * kLanczosA * kLanczosResolution + 1);
256	
257	    static constexpr int kTotalSize = kTriangularSize + kGaussianSize + kCubicSize + kLanczosSize;
258	
259	    ResamplingFiltersFactory()
260	        : m_state([](int deviceId) { return std::make_unique<DeviceFilterState>(deviceId); })
261	    {
262	    }
263	
264	    int GetDeviceComputeCapability() const
265	    {
266	        return m_state.get().computeCapability;
267	    }
268	
269	    ResamplingFilter CreateCubic(float radius = 2.0f) const
270	    {
271	        auto flt = m_state.get().filters[Idx_Cubic];
272	        flt.rescale(2.0f * std::max(2.0f, radius));
273	        return flt;
274	    }
275	
276	    ResamplingFilter CreateGaussian(float sigma) const
277	    {
278	        auto flt = m_state.get().filters[Idx_Gaussian];
279	        flt.rescale(std::max(1.0f, static_cast<float>(4 * M_SQRT2) * sigma));
280	        return flt;
281	    }
282	
283	    ResamplingFilter CreateLanczos3(float radius = 3.0f) const
284	    {
285	        auto flt = m_state.get().filters[Idx_Lanczos3];
286	        flt.rescale(2.0f * std::max(3.0f, radius));
287	        return flt;
288	    }
289	
290	    ResamplingFilter CreateTriangular(float radius) const
291	    {
292	        auto flt = m_state.get().filters[Idx_Triangular];
293	        flt.rescale(std::max(1.0f, 2 * radius));
294	        return flt;
295	    }
296	
297	private:
298	    struct DeviceFilterState
299	    {
300	        std::unique_ptr<float, std::function<void(void *)>> filterDataGpu;
301	        ResamplingFilter                                    filters[kNumFilters];
302	        int                                                 computeCapability{};
303	
304	        explicit DeviceFilterState(int deviceId)
305	        {
306	            int major{};
307	            int minor{};
308	            NVCV_CHECK_THROW(cudaDeviceGetAttribute(&major, cudaDevAttrComputeCapabilityMajor, deviceId));
309	            NVCV_CHECK_THROW(cudaDeviceGetAttribute(&minor, cudaDevAttrComputeCapabilityMinor, deviceId));
310	            computeCapability = major * 10 + minor;
311	
312	            std::unique_ptr<float, std::function<void(void *)>> filterDataPinned;
313	            {
314	                float *ptr = nullptr;
315	                NVCV_CHECK_THROW(cudaMallocHost(&ptr, kTotalSize * sizeof(float)));
316	                filterDataPinned = {ptr, [](void *ptr)
317	                                    {
318	                                        NVCV_CHECK_THROW(cudaFreeHost(ptr));
319	                                    }};
320	            }
321	            {
322	                float *ptr = nullptr;
323	                NVCV_CHECK_THROW(cudaMalloc(&ptr, kTotalSize * sizeof(float)));
324	                filterDataGpu = {ptr, [](void *ptr)
325	                                 {
326	                                     NVCV_CHECK_THROW(cudaFree(ptr));
327	                                 }};
328	            }
329	            auto addFilter = [this, &filterDataPinned](FilterIdx filterIdx, int size)
330	            {
331	                float *base        = filterIdx == 0 ? filterDataPinned.get()
332	                                                    : filters[filterIdx - 1].coeffs + filters[filterIdx - 1].numCoeffs;
333	                filters[filterIdx] = {base, size, 1, (size - 1) * 0.5f};
334	            };
335	            addFilter(Idx_Triangular, kTriangularSize);
336	            InitTriangularFilter(filters[Idx_Triangular]);
337	            addFilter(Idx_Gaussian, kGaussianSize);
338	            InitGaussianFilter(filters[Idx_Gaussian]);
339	            addFilter(Idx_Lanczos3, kLanczosSize);
340	            InitLanczosFilter(filters[Idx_Lanczos3], kLanczosA);
341	            addFilter(Idx_Cubic, kCubicSize);
342	            InitCubicFilter(filters[Idx_Cubic]);
343	
344	            NVCV_CHECK_THROW(cudaMemcpy(filterDataGpu.get(), filterDataPinned.get(), kTotalSize * sizeof(float),
345	                                        cudaMemcpyHostToDevice));
346	            ptrdiff_t diff = filterDataGpu.get() - filterDataPinned.get();
347	            for (auto &f : filters)
348	            {
349	                f.coeffs += diff;
350	            }
351	        }
352	    };
353	
354	    mutable cvcuda::priv::PerDeviceResource<DeviceFilterState> m_state;
355	};
356	
357	inline ResamplingFilter GetResamplingFilter(const ResamplingFiltersFactory &filtersFactory,
358	                                            const FilterMode &filterMode, const float inSize, const float outSize)
359	{
360	    bool antialias = filterMode.antialias && (outSize < inSize);
361	    switch (filterMode.filterType)
362	    {
363	    case FilterType::Linear:
364	    {
365	        return filtersFactory.CreateTriangular(1);
366	    }
367	    break;
368	    case FilterType::Triangular:
369	    {
370	        const float radius = antialias ? inSize / outSize : 1;
371	        return filtersFactory.CreateTriangular(radius);
372	    }
373	    break;
374	    case FilterType::Gaussian:
375	    {
376	        const float radius = antialias ? inSize / outSize : 1;
377	        return filtersFactory.CreateGaussian(radius * 0.5f / M_SQRT2);
378	    }
379	    break;
380	    case FilterType::Cubic:
381	    {
382	        const float radius = antialias ? (2 * inSize / outSize) : 2;
383	        return filtersFactory.CreateCubic(radius);
384	    }
385	    break;
386	    case FilterType::Lanczos3:
387	    {
388	        const float radius = antialias ? (3 * inSize / outSize) : 3;
389	        return filtersFactory.CreateLanczos3(radius);
390	    }
391	    default: // Nearest neighbour
392	    {
393	        return {nullptr, 0, 0, 1};
394	    }
395	    }
396	}
397	
398	} // namespace cvcuda::priv::hq_resize::filter
399	#endif // CVCUDA_PRIV_HQ_RESIZE_FILTER_CUH
