        req.hostMem   = est.hostMem.req;
        req.pinnedMem = est.pinnedMem.req;
        req.cudaMem   = est.cudaMem.req;
        // The allocator requries the total size of the allocation to be aligned
        cvcuda::AlignUp(req);

        return req;
    }

